
DROP TABLE cambios_diag;

create table cambios_diag as (select  cia_bdu, ciap, upper(descriptor) as cadena, fec_apert, fec_cierre  from diagnosticos);


--alter table cambios_diag rename column cia_obf to cia_bdu;
alter table cambios_diag rename column cadena  to descriptor;
commit;

DELETE FROM cambios_diag WHERE cia_bdu IS NULL;
DELETE FROM cambios_diag WHERE cia_bdu LIKE '% %';
DELETE FROM cambios_diag WHERE DESCRIPTOR LIKE '%ERROR%' AND CIAP<>'F91' AND CIAP<>'P06';
DELETE from cambios_diag where DESCRIPTOR like '%EQUIVOCADO%' or DESCRIPTOR like '%ERRONEO%';
DELETE FROM cambios_diag WHERE (DESCRIPTOR LIKE '%?%' OR DESCRIPTOR like '%¿%');
DELETE from cambios_diag where descriptor like '%NO%ACUDE%';
DELETE FROM cambios_diag WHERE CIAP='SAL';
DELETE FROM cambios_diag WHERE CIAP='XXX';
DELETE FROM cambios_diag WHERE CIAP='Z31';
DELETE FROM cambios_diag WHERE CIAP='Q01';
DELETE FROM cambios_diag WHERE CIAP<'994';

-- ERRORES TIPOGRAFICOS---

UPDATE cambios_diag SET cambios_diag.CIAP = 'B02' WHERE (((cambios_diag.CIAP)='BO2'));
